/// <summary>
/// UPSPricingAttribute of table <c>InventTableModule</c> field UnitId.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeInventTableModuleUnitId extends UPSPricingAttributeInventTableModule implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(InventTableModule, UnitId);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::String);

    UnitOfMeasure  unitOfMeasure;

    while select Symbol from unitOfMeasure
    {
        if (!ret.in(unitOfMeasure.Symbol))
        {
            ret.add(unitOfMeasure.Symbol);
        }
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(InventTableModule, UnitId));
    qbr.value(queryValue(_value));
}
